"""Reproduce synthetic inventories; no real host or credential inputs are accepted."""
import argparse
import hashlib
import json
from pathlib import Path

RECIPE = 'box-binder-synthetic-v1'
ROOT = Path(__file__).resolve().parents[1]
FIXTURE = ROOT / 'skills/box-rclone-binder/tests/fixtures/inventories.json'


def inventory(mode='jwt', count=2):
    hosts = [{'host': 'node%d.example.com' % (i + 1), 'remote_name': 'box',
              'auth_mode': mode, 'config_dir': '/etc/box-binder', 'root_folder_id': '0'}
             for i in range(count)]
    if mode == 'oauth-broker':
        for i, host in enumerate(hosts):
            host['broker_role'] = 'master' if i == 0 else 'slave'
    return {'version': 1, 'hosts': hosts, 'secrets': {'source': 'env',
            'jwt_config_ref': 'BOX_TEST_JWT', 'client_id_ref': 'BOX_TEST_ID',
            'client_secret_ref': 'BOX_TEST_SECRET', 'box_subject_id_ref': 'BOX_TEST_SUBJECT',
            'broker_state_ref': 'BOX_TEST_STATE'}}


def canary():
    return 'SYNTHETIC_' + hashlib.sha256(RECIPE.encode()).hexdigest()[:24]


def runtime_receipt(host, action, operation_id, case='matching'):
    """Build a complete synthetic runtime response, with explicit malformed variants."""
    result = {'ok': True, 'host': host['host'], 'auth_mode': host.get('auth_mode', 'jwt'),
              'action': action, 'operation_id': operation_id}
    if case == 'missing':
        result.pop('host')
    elif case == 'other':
        result['host'] = 'other-node.example.com'
    elif case == 'empty':
        result['host'] = ''
    elif case == 'non-string':
        result['host'] = 1
    elif case == 'unsuccessful':
        result['ok'] = False
    elif case == 'stale':
        result['operation_id'] = 'synthetic-old-operation'
    elif case == 'wrong-action':
        result['action'] = 'refresh' if action != 'refresh' else 'validate'
    elif case == 'wrong-mode':
        result['auth_mode'] = 'jwt' if result['auth_mode'] != 'jwt' else 'ccg-native'
    elif case != 'matching':
        raise ValueError('unknown synthetic receipt case')
    return result


def invalid_host_identity(case):
    host = inventory()['hosts'][0]
    if case == 'missing':
        host.pop('host')
    else:
        host['host'] = {'empty': '', 'whitespace': ' ', 'non-string': 1,
                        'nul': 'node\x00.example.com'}[case]
    return host


def access_token():
    return {'access_token': canary(), 'expiry': '2099-01-01T00:00:00Z', 'token_type': 'bearer'}


