def security_inventory_text(case):
    """Generate malicious configuration shapes without using operational data."""
    data = inventory(count=1)
    marker = canary()
    if case == 'json-inline':
        data['metadata'] = {'client_secret': marker}
    elif case == 'nested-list':
        data['metadata'] = [{'access_token': marker}]
    elif case == 'host-literal-ref':
        data['hosts'][0]['secrets'] = {'client_secret_ref': marker}
    elif case == 'host-secret-value':
        data['hosts'][0]['secrets'] = {'client_secret': marker}
    elif case == 'nested-secret-section':
        data['metadata'] = {'secrets': marker}
    elif case == 'nested-literal-ref':
        data['metadata'] = {'client_secret_ref': marker}
    elif case == 'duplicate-mapping':
        return json.dumps(data)[:-1] + ', "metadata": {"client_secret": ' + json.dumps(marker) + '}, "metadata": {}}'
    elif case in ('quoted-inline', 'flow-inline'):
        base = ('version: 1\nhosts:\n  - host: node1.example.com\n'
                '    remote_name: box\n    auth_mode: jwt\n')
        value = json.dumps(marker)
        suffix = ('metadata:\n  "client_secret": ' + value + '\n' if case == 'quoted-inline'
                  else 'metadata: {"client_secret": ' + value + '}\n')
        return base + suffix
    else:
        raise ValueError('unknown synthetic configuration case')
    return json.dumps(data)


def malformed_inventory(case):
    """Return one malformed schema input per independently named contract."""
    data = inventory(count=1)
    values = {'version-bool': True, 'version-string': '1', 'version-future': 2,
              'version-null': None, 'version-float': 1.0}
    if case in values:
        data['version'] = values[case]
    elif case == 'alias-conflict':
        data['schema_version'] = 2
    elif case == 'root-list':
        return []
    elif case in ('defaults-list', 'secrets-list', 'alerts-list'):
        data[case.split('-')[0]] = []
    elif case == 'defaults-pairs':
        data['defaults'] = [['remote_name', 'box']]
    elif case == 'hosts-mapping':
        data['hosts'] = {'host': 'node1.example.com'}
    elif case == 'hosts-null-item':
        data['hosts'] = [None]
    elif case == 'host-secrets-list':
        data['hosts'][0]['secrets'] = []
    elif case == 'host-secrets-literal':
        data['hosts'][0]['secrets'] = canary()
    elif case == 'remote-name-bool':
        data['hosts'][0]['remote_name'] = True
    elif case == 'reference-number':
        data['secrets']['client_secret_ref'] = 1
    else:
        raise ValueError('unknown synthetic schema case')
    return data


