def observed_runtime_receipt(host, action, operation_id, case='matching'):
    """Supply synthetic target observations separately from controller configuration."""
    result = runtime_receipt(host, action, operation_id)
    settings = {'auth_mode': 'jwt', 'root_folder_id': '0', 'box_sub_type': 'enterprise',
                'remote_name': 'box'}
    if case == 'drift':
        settings.update(root_folder_id='987654', remote_name='box_other')
    elif case == 'missing':
        return result
    elif case == 'malformed':
        settings['root_folder_id'] = ['987654']
    elif case == 'empty':
        settings['remote_name'] = ''
    elif case == 'incomplete':
        settings.pop('box_sub_type')
    elif case != 'matching':
        raise ValueError('unknown synthetic observation case')
    result['observed_settings'] = settings
    return result


